// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'landing-ship-cabin',
  role: 'building',
  reference: 'models and assets images/phase-4/landing-ship-cabin.png'
};

function build() {
  const root = createRoot('landing-ship-cabin');
  const m = styleMaterials();
  m.panel.flatShading = false;
  m.panelGray.flatShading = false;

  // -------------------------------------------------------------------------
  // 1. EXTERIOR LOWER BASE, LEGS & ENGINE NOZZLES
  // -------------------------------------------------------------------------
  createPart('OrangeSkirt', cylinderGeo(1.85, 1.95, 0.42, 8), m.accent, {
    position: [0, 0.65, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });

  createPart('HullBelt', cylinderGeo(1.92, 1.92, 0.16, 8), m.panelGray, {
    position: [0, 0.90, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });

  // Four rocket engine nozzles
  const nozzlePositions = [
    [0.72, 0.28, 0.72],
    [-0.72, 0.28, 0.72],
    [0.72, 0.28, -0.72],
    [-0.72, 0.28, -0.72]
  ];
  nozzlePositions.forEach(([nx, ny, nz], i) => {
    createPart('NozzleCone_' + (i + 1), cylinderGeo(0.24, 0.38, 0.36, 12), m.panelGray, {
      position: [nx, ny, nz],
      parent: root
    });
    createPart('NozzleThroat_' + (i + 1), cylinderGeo(0.25, 0.25, 0.08, 12), m.trim, {
      position: [nx, ny + 0.16, nz],
      parent: root
    });
  });

  // Four articulated landing gear legs & footpads reaching Y = 0
  const legAngles = [45, 135, 225, 315];
  legAngles.forEach((deg, i) => {
    const rad = (deg * Math.PI) / 180;
    const legX = Math.cos(rad) * 1.75;
    const legZ = Math.sin(rad) * 1.75;
    const footX = Math.cos(rad) * 2.15;
    const footZ = Math.sin(rad) * 2.15;

    createPart('Footpad_' + (i + 1), cylinderGeo(0.32, 0.38, 0.08, 8), m.panelGray, {
      position: [footX, 0.04, footZ],
      rotation: [0, deg, 0],
      parent: root
    });
    createPart('LegAnkle_' + (i + 1), cylinderGeo(0.14, 0.15, 0.18, 8), m.panelGray, {
      position: [footX, 0.16, footZ],
      parent: root
    });
    createPart('LegStrut_' + (i + 1), cylinderGeo(0.11, 0.11, 0.60, 8), m.panelGray, {
      position: [(legX + footX) / 2, 0.45, (legZ + footZ) / 2],
      rotation: [0, -deg, 38],
      parent: root
    });
    createPart('LegBracket_' + (i + 1), boxGeo(0.22, 0.32, 0.22), m.panelGray, {
      position: [legX, 0.65, legZ],
      rotation: [0, deg, 0],
      parent: root
    });
  });

  // -------------------------------------------------------------------------
  // 2. CABIN ENCLOSURE & CUTAWAY PORTAL
  // Cutaway faces +X and +X/+Z (viewer looks into cabin from front 3/4)
  // -------------------------------------------------------------------------
  createPart('CabinFloor', cylinderGeo(1.78, 1.78, 0.10, 8), m.panelGray, {
    position: [0, 0.85, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });
  createPart('FloorOrangeInlay', cylinderGeo(1.45, 1.45, 0.015, 8), m.accent, {
    position: [0, 0.908, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });
  createPart('FloorCenterPlate', cylinderGeo(1.36, 1.36, 0.018, 8), m.panelGray, {
    position: [0, 0.91, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });

  // Aft Back Wall (-X)
  createPart('WallBackAft', boxGeo(0.12, 1.80, 2.40), m.panel, {
    position: [-1.60, 1.85, 0],
    parent: root
  });
  createPart('WallBackRib', boxGeo(0.14, 1.80, 0.16), m.panelGray, {
    position: [-1.58, 1.85, 0],
    parent: root
  });

  // Left Wall (+Z): Console & Window wall (extends from X = -1.45 to X = 0.40)
  createPart('WallLeft', boxGeo(1.85, 1.80, 0.12), m.panel, {
    position: [-0.50, 1.85, 1.60],
    parent: root
  });

  // Right Wall (-Z): O2 canister & Side Hatch wall (extends from X = -1.45 to X = 1.15)
  createPart('WallRight', boxGeo(2.40, 1.80, 0.12), m.panel, {
    position: [-0.10, 1.85, -1.60],
    parent: root
  });

  // Corner chamfer wall posts
  createPart('CornerPost_BL', boxGeo(0.36, 1.80, 0.36), m.panelGray, {
    position: [-1.35, 1.85, 1.35],
    rotation: [0, 45, 0],
    parent: root
  });
  createPart('CornerPost_BR', boxGeo(0.36, 1.80, 0.36), m.panelGray, {
    position: [-1.35, 1.85, -1.35],
    rotation: [0, 45, 0],
    parent: root
  });

  // Front Cutaway Heavy Slate Arch Framing
  createPart('ArchPostLeft', boxGeo(0.24, 1.80, 0.28), m.panelGray, {
    position: [0.45, 1.85, 1.55],
    parent: root
  });
  createPart('ArchPostRight', boxGeo(0.24, 1.80, 0.28), m.panelGray, {
    position: [1.25, 1.85, -1.45],
    parent: root
  });
  createPart('ArchTopLintel', boxGeo(0.24, 0.28, 2.70), m.panelGray, {
    position: [0.85, 2.70, 0.05],
    rotation: [0, -18, 0],
    parent: root
  });
  createPart('ArchThreshold', boxGeo(0.24, 0.18, 2.70), m.panelGray, {
    position: [0.85, 0.95, 0.05],
    rotation: [0, -18, 0],
    parent: root
  });

  // -------------------------------------------------------------------------
  // 3. ROOF, CEILING LIGHT & BEACON
  // -------------------------------------------------------------------------
  createPart('RoofShell', cylinderGeo(1.65, 1.92, 0.50, 8), m.panel, {
    position: [0, 2.95, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });
  const roofPads = [[0.9, 0.9], [-0.9, 0.9], [0.9, -0.9], [-0.9, -0.9]];
  roofPads.forEach(([rx, rz], i) => {
    createPart('RoofTrimPad_' + (i + 1), boxGeo(0.35, 0.08, 0.35), m.panelGray, {
      position: [rx, 3.22, rz],
      parent: root
    });
  });

  // Top central cyan beacon
  createPart('BeaconBase', cylinderGeo(0.28, 0.32, 0.10, 8), m.panelGray, {
    position: [0, 3.24, 0],
    parent: root
  });
  createPart('BeaconLight', cylinderGeo(0.18, 0.18, 0.16, 8), m.glowCool, {
    position: [0, 3.37, 0],
    parent: root
  });
  createPart('BeaconCap', cylinderGeo(0.20, 0.20, 0.05, 8), m.panelGray, {
    position: [0, 3.47, 0],
    parent: root
  });

  // Interior warm glowing ceiling light fixture
  createPart('CeilingLightBezel', boxGeo(0.85, 0.04, 1.30), m.accent, {
    position: [-0.10, 2.71, 0],
    parent: root
  });
  createPart('CeilingLightEmitter', boxGeo(0.75, 0.03, 1.15), m.glowWarm, {
    position: [-0.10, 2.69, 0],
    parent: root
  });

  // -------------------------------------------------------------------------
  // 4. PILOT SEAT (`seat` node)
  // Centered, angled 45 degrees towards the Console & Window
  // -------------------------------------------------------------------------
  const seatNode = createPivot('seat', [-0.05, 0.92, 0.15], root);

  createPart('SeatPedestal', cylinderGeo(0.26, 0.30, 0.14, 8), m.panelGray, {
    position: [0, 0.07, 0],
    parent: seatNode
  });
  createPart('SeatShell', boxGeo(0.55, 0.20, 0.52), m.panelGray, {
    position: [0, 0.22, 0],
    rotation: [0, 38, 0],
    parent: seatNode
  });
  createPart('SeatCushion', boxGeo(0.48, 0.10, 0.46), m.accent, {
    position: [-0.01, 0.28, 0.01],
    rotation: [0, 38, 0],
    parent: seatNode
  });
  createPart('BackrestShell', boxGeo(0.14, 0.65, 0.48), m.panelGray, {
    position: [0.18, 0.58, -0.14],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  createPart('BackrestCushion', boxGeo(0.08, 0.58, 0.42), m.accent, {
    position: [0.14, 0.58, -0.11],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  createPart('HeadrestShell', boxGeo(0.12, 0.18, 0.32), m.panelGray, {
    position: [0.23, 0.95, -0.18],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  createPart('HeadrestCushion', boxGeo(0.07, 0.15, 0.28), m.accent, {
    position: [0.19, 0.95, -0.15],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  // Harness straps & central buckle
  createPart('HarnessLeft', boxGeo(0.02, 0.50, 0.05), m.panelGray, {
    position: [0.12, 0.58, -0.05],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  createPart('HarnessRight', boxGeo(0.02, 0.50, 0.05), m.panelGray, {
    position: [0.16, 0.58, -0.17],
    rotation: [6, 38, 8],
    parent: seatNode
  });
  createPart('HarnessBuckle', cylinderGeo(0.04, 0.04, 0.02, 8), m.panelGray, {
    position: [0.10, 0.42, -0.08],
    rotation: [0, 38, 90],
    parent: seatNode
  });
  // Armrests
  createPart('ArmrestL', boxGeo(0.38, 0.06, 0.08), m.panelGray, {
    position: [-0.17, 0.40, 0.22],
    rotation: [0, 38, 0],
    parent: seatNode
  });
  createPart('ArmrestR', boxGeo(0.38, 0.06, 0.08), m.panelGray, {
    position: [0.17, 0.40, -0.22],
    rotation: [0, 38, 0],
    parent: seatNode
  });

  // -------------------------------------------------------------------------
  // 5. SLOPED INSTRUMENT CONSOLE, WINDOW & ARM BUTTON
  // Along left wall (+Z, centered at Z = +1.15)
  // -------------------------------------------------------------------------
  const consoleGroup = createPivot('ConsoleGroup', [-0.35, 0.92, 1.15], root);

  createPart('ConsoleBase', boxGeo(1.30, 0.45, 0.55), m.accent, {
    position: [0, 0.22, 0],
    parent: consoleGroup
  });
  createPart('ConsoleTop', boxGeo(1.36, 0.08, 0.62), m.panel, {
    position: [0, 0.48, 0],
    parent: consoleGroup
  });
  createPart('ConsoleWedge', boxGeo(1.20, 0.24, 0.45), m.panel, {
    position: [0, 0.60, 0.05],
    rotation: [-22, 0, 0],
    parent: consoleGroup
  });

  // Embedded Landing Screen (`screen_anchor`)
  const screenAnchor = createPivot('screen_anchor', [0.05, 0.66, 0.02], consoleGroup);
  createPart('ScreenBezel', boxGeo(0.44, 0.26, 0.02), m.panelGray, {
    position: [0, 0, 0],
    rotation: [-22, 0, 0],
    parent: screenAnchor
  });
  createPart('ScreenGlass', boxGeo(0.38, 0.20, 0.025), m.glowCool, {
    position: [0, 0, -0.01],
    rotation: [-22, 0, 0],
    parent: screenAnchor
  });

  // Prominent physical orange ARM Button (`button_arm`)
  const armBtnNode = createPivot('button_arm', [-0.28, 0.66, 0.02], consoleGroup);
  createPart('ArmBezel', boxGeo(0.18, 0.18, 0.03), m.panelGray, {
    position: [0, 0, 0],
    rotation: [-22, 0, 0],
    parent: armBtnNode
  });
  createPart('ArmButtonCap', boxGeo(0.13, 0.13, 0.05), m.accent, {
    position: [0, 0, -0.02],
    rotation: [-22, 0, 0],
    parent: armBtnNode
  });

  createPart('SwitchBtn1', boxGeo(0.08, 0.08, 0.03), m.panelGray, {
    position: [0.36, 0.66, 0.02],
    rotation: [-22, 0, 0],
    parent: consoleGroup
  });
  createPart('SwitchBtn2', boxGeo(0.08, 0.08, 0.03), m.panelGray, {
    position: [0.47, 0.66, 0.02],
    rotation: [-22, 0, 0],
    parent: consoleGroup
  });

  // Forward Viewport Window above Console on Left Wall (+Z = 1.52)
  const windowNode = createPivot('window', [-0.35, 2.05, 1.52], root);
  createPart('WindowFrame', boxGeo(1.60, 0.70, 0.14), m.panelGray, {
    position: [0, 0, 0],
    parent: windowNode
  });
  createPart('WindowGlass', boxGeo(1.42, 0.54, 0.15), m.visor, {
    position: [0, 0, 0],
    parent: windowNode
  });

  // -------------------------------------------------------------------------
  // 6. AFT WALL INNER AIRLOCK HATCH (`hatch` node)
  // On aft wall (-X = -1.54, centered at Z = -0.30)
  // -------------------------------------------------------------------------
  const hatchNode = createPivot('hatch', [-1.52, 1.70, -0.30], root);

  createPart('HatchFrameOuter', cylinderGeo(0.58, 0.62, 0.12, 8), m.panelGray, {
    position: [0, 0, 0],
    rotation: [0, 0, 90],
    parent: hatchNode
  });
  createPart('HatchOrangeBorder', cylinderGeo(0.50, 0.54, 0.14, 8), m.accent, {
    position: [0.01, 0, 0],
    rotation: [0, 0, 90],
    parent: hatchNode
  });
  createPart('HatchDoorPlate', cylinderGeo(0.42, 0.44, 0.15, 8), m.panelGray, {
    position: [0.02, 0, 0],
    rotation: [0, 0, 90],
    parent: hatchNode
  });
  createPart('HatchWheelCenter', cylinderGeo(0.08, 0.08, 0.05, 8), m.trim, {
    position: [0.09, 0, 0],
    rotation: [0, 0, 90],
    parent: hatchNode
  });

  // -------------------------------------------------------------------------
  // 7. RIGHT WALL: EMERGENCY O2 CANISTER & EXTERIOR SIDE HATCH WITH LADDER
  // Right wall at -Z = -1.54
  // -------------------------------------------------------------------------
  const o2Group = createPivot('o2_canister', [-0.85, 1.85, -1.48], root);
  createPart('O2BracketTop', boxGeo(0.18, 0.04, 0.14), m.panelGray, {
    position: [0, 0.22, 0],
    parent: o2Group
  });
  createPart('O2BracketBot', boxGeo(0.18, 0.04, 0.14), m.panelGray, {
    position: [0, -0.20, 0],
    parent: o2Group
  });
  createPart('O2Body', cylinderGeo(0.12, 0.12, 0.38, 12), m.accent, {
    position: [0, 0, 0],
    parent: o2Group
  });
  createPart('O2Collar', cylinderGeo(0.08, 0.10, 0.08, 10), m.panelGray, {
    position: [0, 0.23, 0],
    parent: o2Group
  });
  createPart('O2Handle', boxGeo(0.04, 0.10, 0.12), m.panelGray, {
    position: [0, 0.30, 0],
    parent: o2Group
  });
  createPart('O2Led', cylinderGeo(0.02, 0.02, 0.03, 8), m.glowCool, {
    position: [0.08, 0.12, 0],
    rotation: [0, 0, 90],
    parent: o2Group
  });

  // Exterior Side Hatch Door (X = 0.45, Y = 1.65, Z = -1.54)
  const sideHatch = createPivot('side_hatch', [0.45, 1.65, -1.52], root);
  createPart('SideHatchFrame', cylinderGeo(0.48, 0.52, 0.14, 8), m.panelGray, {
    position: [0, 0, 0],
    rotation: [90, 0, 0],
    parent: sideHatch
  });
  createPart('SideHatchBorder', cylinderGeo(0.40, 0.44, 0.16, 8), m.accent, {
    position: [0, 0, -0.01],
    rotation: [90, 0, 0],
    parent: sideHatch
  });
  createPart('SideHatchDoor', cylinderGeo(0.34, 0.36, 0.18, 8), m.panelGray, {
    position: [0, 0, -0.02],
    rotation: [90, 0, 0],
    parent: sideHatch
  });

  // Exterior Stairs / Ladder extending down from side hatch to ground Y = 0
  const ladderGroup = createPivot('stairs', [0.45, 0.48, -1.85], root);
  createPart('LadderStringerL', boxGeo(0.10, 0.98, 0.05), m.panelGray, {
    position: [-0.22, 0, 0],
    rotation: [0, 0, 32],
    parent: ladderGroup
  });
  createPart('LadderStringerR', boxGeo(0.10, 0.98, 0.05), m.panelGray, {
    position: [0.22, 0, 0],
    rotation: [0, 0, 32],
    parent: ladderGroup
  });
  for (let rung = -0.30; rung <= 0.30; rung += 0.15) {
    createPart('Rung_' + Math.round(rung * 100), boxGeo(0.38, 0.04, 0.08), m.panelGray, {
      position: [0, rung, 0],
      parent: ladderGroup
    });
  }

  defineBudget({ triangles: BUDGETS['building'] }, root);
  return root;
}
